using Microsoft.EntityFrameworkCore;
namespace Decont;
public class BankTreatment {public Guid Id{get;set;}=Guid.NewGuid();public Guid TransactionId{get;set;}public Guid ReportId{get;set;}public string Kind{get;set;}="";public decimal PrincipalRon{get;set;}public decimal FeeRon{get;set;}public decimal MarkupRon{get;set;}public Guid EvidenceId{get;set;}public string Fingerprint{get;set;}="";public string Json{get;set;}="{}";public string Actor{get;set;}="";public string Reason{get;set;}="";public DateTime At{get;set;}=DateTime.UtcNow;}
public class BankTreatmentRevocation {public Guid Id{get;set;}=Guid.NewGuid();public Guid TreatmentId{get;set;}public string Actor{get;set;}="";public string Reason{get;set;}="";public DateTime At{get;set;}=DateTime.UtcNow;}
public record BankTreatmentCommand(Guid ReportId,long Version,string Kind,decimal PrincipalRon,decimal FeeRon,decimal MarkupRon,Guid EvidenceId,string Category,string CostCenter,string Reason,bool ConfirmReapproval=false);
public static class BankTreatments {
 public static string Fingerprint(CardTransaction t)=>Serialization.Hash(Serialization.Write(new{t.CardId,t.Reference,t.Date,t.Merchant,t.Amount,t.Currency,t.SettledRon}));
 public static async Task<decimal> Principal(Db db,CardTransaction t){var treatment=await db.BankTreatments.SingleOrDefaultAsync(x=>x.TransactionId==t.Id&&!db.BankTreatmentRevocations.Any(r=>r.TreatmentId==x.Id));Guard.Require(treatment==null||treatment.Fingerprint==Fingerprint(t),"bank_source_changed","Tranzacția sursă s-a modificat. Verifică și reclasifică extrasul.","Source transaction changed. Review and reclassify the statement.",409);return treatment?.PrincipalRon??t.SettledRon;}
 public static void Validate(CardTransaction t,BankTreatmentCommand i){Guard.Require(i.Kind is "NORMAL" or "SEPARATE_CHARGES" or "REVERSAL","bank_treatment","Selectează tratamentul tranzacției.","Select transaction treatment.");var sign=Math.Sign(t.SettledRon);Guard.Require(i.PrincipalRon!=0&&Math.Sign(i.PrincipalRon)==sign&&new[]{i.PrincipalRon,i.FeeRon,i.MarkupRon}.All(x=>x==Rules.Money(x)&&(x==0||Math.Sign(x)==sign))&&i.PrincipalRon+i.FeeRon+i.MarkupRon==t.SettledRon,"bank_breakdown","Principalul, comisioanele și adaosul trebuie să recompună exact suma RON a extrasului, cu același semn.","Principal, fees and markup must exactly reconcile statement RON with matching signs.");Guard.Require(i.Kind=="SEPARATE_CHARGES"?i.FeeRon!=0||i.MarkupRon!=0:i.FeeRon==0&&i.MarkupRon==0,"bank_treatment","Alege separarea comisioanelor dacă extrasul conține costuri suplimentare.","Select separate charges when the statement includes additional costs.");Guard.Require(i.Kind!="REVERSAL"||t.Amount<0,"bank_reversal","Tranzacția selectată nu are sumă negativă.","Selected transaction is not negative.");}
 public static void Map(RouteGroupBuilder api){var f=api.MapGroup("/finance").RequireAuthorization(p=>p.RequireRole("Finance"));
 f.MapGet("/bank-treatments",async(Db db)=>new{treatments=await db.BankTreatments.OrderByDescending(x=>x.At).ToListAsync(),revocations=await db.BankTreatmentRevocations.ToListAsync()});
 f.MapPost("/bank-treatments/{id:guid}/undo",async(Guid id,VersionRequest i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);var treatment=await db.BankTreatments.FindAsync(id)??throw new DomainException("not_found","Clasificarea nu există.","Classification not found.",404);var report=await svc.Version(treatment.ReportId,i.Version,c.User);svc.Edit(report,c.User,i.Reason);Guard.Require(States.FinanceEdit(report.State)&&!await db.BankTreatmentRevocations.AnyAsync(x=>x.TreatmentId==id),"bank_locked","Clasificarea nu mai poate fi anulată.","Classification can no longer be undone.",409);var json=System.Text.Json.JsonDocument.Parse(treatment.Json);var ids=json.RootElement.GetProperty("createdExpenseIds").EnumerateArray().Select(x=>x.GetGuid()).ToList();Guard.Require(!await db.Matches.AnyAsync(m=>m.TransactionId==treatment.TransactionId||ids.Contains(m.LineId)),"bank_locked","Anulează mai întâi toate alocările asociate.","Undo all associated allocations first.",409);foreach(var line in report.Lines.Where(l=>ids.Contains(l.Id))){line.Archived=true;FinancialCalculations.Invalidate(line,true);}db.BankTreatmentRevocations.Add(new(){TreatmentId=id,Actor=Reports.Actor(c.User),Reason=i.Reason!});Reports.Touch(report);svc.Log(c.User,report.Id,id.ToString(),"BankTreatmentUndone",before:treatment,reason:i.Reason);await svc.Reapproval(report,c.User,i.ConfirmReapproval);return Api.View(report);}));
 f.MapPost("/transactions/{id:guid}/treatment",async(Guid id,BankTreatmentCommand i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);var report=await svc.Version(i.ReportId,i.Version,c.User);Guard.Require(States.FinanceEdit(report.State),"state","Clasifică tranzacția în verificarea Finance.","Classify the transaction during Finance review.");svc.Edit(report,c.User,i.Reason);var transaction=await db.Transactions.FindAsync(id)??throw new DomainException("not_found","Tranzacția nu există.","Transaction not found.",404);Guard.Require(report.Payment=="CompanyCard"&&report.CardId==transaction.CardId,"bank_card","Tranzacția trebuie să aparțină cardului decontului.","Transaction must belong to the report card.");Guard.Require(!await db.Matches.AnyAsync(m=>m.TransactionId==id)&&!await db.BankTreatments.AnyAsync(x=>x.TransactionId==id&&!db.BankTreatmentRevocations.Any(r=>r.TreatmentId==x.Id)),"bank_locked","Anulează alocările înainte de clasificare; o clasificare confirmată nu se suprascrie.","Undo allocations before classifying; an accepted classification cannot be overwritten.",409);Validate(transaction,i);IOriginalDocument? evidence=report.Attachments.Where(e=>!e.Archived&&e.Scan=="Clean").Cast<IOriginalDocument>().Concat(report.Lines.SelectMany(l=>l.Evidence).Where(e=>!e.Archived&&e.Scan=="Clean")).SingleOrDefault(e=>e.Id==i.EvidenceId);Guard.Require(evidence!=null,"bank_evidence","Atașează extrasul unui bon sau în documentele comune și așteaptă scanarea.","Attach the statement to a receipt or report documents and wait for scanning.");var charges=new List<(decimal Amount,string Ro,string En)>();if(i.FeeRon!=0)charges.Add((i.FeeRon,"Comision bancar","Bank fee"));if(i.MarkupRon!=0)charges.Add((i.MarkupRon,"Adaos valutar bancar","Bank FX markup"));Guard.Require(report.Lines.Count(l=>!l.Archived)+charges.Count<=Rules.MaxLines,"limit","Limita este de 50 de cheltuieli active.","Maximum 50 active expenses.");var created=new List<Guid>();foreach(var charge in charges){var line=new Line{ReportId=report.Id,Position=report.Lines.Count+1};await svc.Apply(line,new("",null,transaction.Reference,transaction.Date,"RO","Receipt",i.Category,charge.Ro+" / "+charge.En+": "+transaction.Reference,"CompanyCard",transaction.CardId,i.CostCenter,null,charge.Amount,"RON",[],false));line.OverrideReason="BANK_CHARGE:"+i.Reason;report.Lines.Add(line);db.Lines.Add(line);created.Add(line.Id);}ReportAttachment? shared=evidence as ReportAttachment;if(created.Count>0){if(shared==null){shared=new ReportAttachment{ReportId=report.Id,UploadedBy=Reports.Actor(c.User),Name=evidence!.Name,Key=evidence.Key,Mime=evidence.Mime,Size=evidence.Size,Hash=evidence.Hash,Scan="Clean",CoveredLines=Serialization.Write(created)};report.Attachments.Add(shared);db.ReportAttachments.Add(shared);}else shared.CoveredLines=Serialization.Write(Serialization.Read<List<Guid>>(shared.CoveredLines).Union(created).ToList());}var treatment=new BankTreatment{TransactionId=id,ReportId=report.Id,Kind=i.Kind,PrincipalRon=i.PrincipalRon,FeeRon=i.FeeRon,MarkupRon=i.MarkupRon,EvidenceId=i.EvidenceId,Fingerprint=Fingerprint(transaction),Json=Serialization.Write(new{original=transaction,createdExpenseIds=created,statement=new{evidence!.Id,evidence.Name,evidence.Hash,evidence.Mime},sharedStatementId=shared?.Id,policy="EXPLICIT_FINANCE_SEPARATE_CHARGES",employee=report.EmployeeId}),Actor=Reports.Actor(c.User),Reason=i.Reason};db.BankTreatments.Add(treatment);Reports.Touch(report);svc.Log(c.User,report.Id,id.ToString(),"BankTreatmentConfirmed",after:treatment,reason:i.Reason);await svc.Reapproval(report,c.User,i.ConfirmReapproval);return new{treatment,report=Api.View(report)};}));
 }
}
